  { id: 'estrela', emoji: '🌟', nome: 'Estrela da UniMax', descricao: 'Recebeu 200 curtidas', bonus: 100, atingiu: (s) => s.curtidas >= 200 },
  { id: 'medalhista', emoji: '🏅', nome: 'Medalhista', descricao: 'Ganhou a primeira medalha de um professor', bonus: 20, atingiu: (s) => s.medalhas >= 1 },
  { id: 'colecionador', emoji: '🏆', nome: 'Colecionador', descricao: 'Ganhou 5 medalhas de professores', bonus: 60, atingiu: (s) => s.medalhas >= 5 },
];

// Medalhas que os professores podem dar (criadas no banco na primeira execução).
const MEDALHAS_PADRAO = [
  { nome: 'Excelência acadêmica', emoji: '🥇', pontos: 50, descricao: 'Desempenho excepcional na disciplina' },
  { nome: 'Projeto destaque', emoji: '🚀', pontos: 40, descricao: 'Entregou um projeto que se destacou' },
  { nome: 'Ideia brilhante', emoji: '💡', pontos: 30, descricao: 'Trouxe uma ideia ou solução criativa' },
  { nome: 'Ajudou os colegas', emoji: '🤝', pontos: 30, descricao: 'Ajudou a turma a aprender' },
  { nome: 'Participação em aula', emoji: '🙋', pontos: 20, descricao: 'Participou ativamente das aulas' },
];

module.exports = { PONTOS, CONQUISTAS, MEDALHAS_PADRAO };

const crypto = require('node:crypto');

function hashSenha(senha) {
  const sal = crypto.randomBytes(16);
  const hash = crypto.scryptSync(senha, sal, 64);
  return `${sal.toString('hex')}:${hash.toString('hex')}`;
}

function confereSenha(senha, armazenado) {
  const [sal, hash] = String(armazenado).split(':');
  if (!sal || !hash) return false;
  const calculado = crypto.scryptSync(senha, Buffer.from(sal, 'hex'), 64);
  const esperado = Buffer.from(hash, 'hex');
  return esperado.length === calculado.length && crypto.timingSafeEqual(calculado, esperado);
}

module.exports = { hashSenha, confereSenha };

const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');
const config = require('./config');
const { MEDALHAS_PADRAO } = require('./regras');
const { hashSenha } = require('./senha');

fs.mkdirSync(config.PASTA_DADOS, { recursive: true });
const db = new DatabaseSync(path.join(config.PASTA_DADOS, 'maxx.db'));

db.exec(`
PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

CREATE TABLE IF NOT EXISTS usuarios (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  senha_hash TEXT NOT NULL,
  papel TEXT NOT NULL DEFAULT 'aluno' CHECK (papel IN ('aluno', 'professor', 'admin')),
  curso TEXT,
  bio TEXT NOT NULL DEFAULT '',
  avatar TEXT,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS sessoes (
  token_hash TEXT PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  expira_em INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS posts (
  id INTEGER PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  imagem TEXT,
  legenda TEXT NOT NULL DEFAULT '',
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_posts_usuario ON posts(usuario_id);

CREATE TABLE IF NOT EXISTS curtidas (
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, usuario_id)
);

CREATE TABLE IF NOT EXISTS comentarios (
  id INTEGER PRIMARY KEY,
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  texto TEXT NOT NULL,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_comentarios_post ON comentarios(post_id);

CREATE TABLE IF NOT EXISTS tipos_medalha (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  emoji TEXT NOT NULL,
  pontos INTEGER NOT NULL,
  descricao TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS medalhas (
  id INTEGER PRIMARY KEY,
  aluno_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  professor_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
  tipo_id INTEGER NOT NULL REFERENCES tipos_medalha(id),
  mensagem TEXT NOT NULL DEFAULT '',
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_medalhas_aluno ON medalhas(aluno_id);

CREATE TABLE IF NOT EXISTS avisos (
  id INTEGER PRIMARY KEY,
  autor_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
  titulo TEXT NOT NULL,
  texto TEXT NOT NULL,
  fixado INTEGER NOT NULL DEFAULT 0,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
`);

// Dados iniciais: tipos de medalha e conta da faculdade.
if (db.prepare('SELECT COUNT(*) AS n FROM tipos_medalha').get().n === 0) {
  const inserir = db.prepare('INSERT INTO tipos_medalha (nome, emoji, pontos, descricao) VALUES (?, ?, ?, ?)');
  for (const m of MEDALHAS_PADRAO) inserir.run(m.nome, m.emoji, m.pontos, m.descricao);
}

if (!db.prepare("SELECT 1 FROM usuarios WHERE papel = 'admin'").get()) {
  db.prepare("INSERT INTO usuarios (nome, email, senha_hash, papel, bio) VALUES (?, ?, ?, 'admin', ?)").run(
    config.FACULDADE,
    config.ADMIN_EMAIL,
    hashSenha(config.ADMIN_SENHA),
    'Conta oficial da faculdade',
  );
  console.log(`Conta da faculdade criada: ${config.ADMIN_EMAIL} / senha: ${config.ADMIN_SENHA} (troque depois!)`);
}

module.exports = db;

// Cálculo de pontos, conquistas e rankings.
// Tudo é calculado a partir dos dados reais: se um post ou curtida
// for apagado, a pontuação se ajusta sozinha.
const db = require('./db');
const { PONTOS, CONQUISTAS } = require('./regras');

const SQL_STATS = `
SELECT u.id, u.nome, u.curso, u.avatar,
  (SELECT COUNT(*) FROM posts p WHERE p.usuario_id = u.id) AS posts,
  (SELECT COUNT(DISTINCT c.post_id) FROM comentarios c JOIN posts p ON p.id = c.post_id
     WHERE c.usuario_id = u.id AND p.usuario_id <> u.id) AS comentarios,
  (SELECT COUNT(*) FROM curtidas l JOIN posts p ON p.id = l.post_id
     WHERE p.usuario_id = u.id AND l.usuario_id <> u.id) AS curtidas,
  (SELECT COUNT(*) FROM medalhas m WHERE m.aluno_id = u.id) AS medalhas,
  (SELECT COALESCE(SUM(t.pontos), 0) FROM medalhas m JOIN tipos_medalha t ON t.id = m.tipo_id
     WHERE m.aluno_id = u.id) AS pontos_medalhas
FROM usuarios u
WHERE u.papel = 'aluno'`;

function calcular(s) {
  const conquistas = CONQUISTAS.filter((c) => c.atingiu(s));
  const pontosConquistas = conquistas.reduce((soma, c) => soma + c.bonus, 0);
  const total =
    s.posts * PONTOS.post +
    s.comentarios * PONTOS.comentario +
    s.curtidas * PONTOS.curtida +
    s.pontos_medalhas +
    pontosConquistas;
  return { ...s, conquistas, pontos_conquistas: pontosConquistas, total };
}

function ranking(curso) {
  let lista = db.prepare(SQL_STATS).all().map(calcular);
  if (curso) lista = lista.filter((a) => a.curso === curso);
  lista.sort((a, b) => b.total - a.total || a.nome.localeCompare(b.nome, 'pt-BR'));
  // Empatados ficam na mesma posição.
  lista.forEach((a, i) => {
    a.posicao = i > 0 && lista[i - 1].total === a.total ? lista[i - 1].posicao : i + 1;
  });
  return lista;
}

function statsDoAluno(id) {
  const row = db.prepare(SQL_STATS + ' AND u.id = ?').get(id);
  if (!row) return null;
  const s = calcular(row);
  s.posicao_geral = ranking().find((a) => a.id === id)?.posicao;
  s.posicao_curso = s.curso ? ranking(s.curso).find((a) => a.id === id)?.posicao : null;
  return s;
}

module.exports = { ranking, statsDoAluno };

